    private func _validateArgumentTypes(_ importer: any IAlphaTexImporter, _ signatures: List<AlphaTexSignatureDefinition>, _ parent: AlphaTexAstNode, _ args: AlphaTexArgumentList?) throws -> Bool {
        if !TypeHelper.isTruthy(args) {
            let hasEmptyParameterOverload: Bool = signatures.some({ (c: AlphaTexSignatureDefinition) -> Bool in
                return c.parameters.length == 0.0 || (!c.parameters.some({ (v: AlphaTexParameterDefinition) -> Bool in
                    return v.parseMode == ArgumentListParseTypesMode.Required || v.parseMode == ArgumentListParseTypesMode.RequiredAsFloat || v.parseMode == ArgumentListParseTypesMode.RequiredAsValueList
                }) as! Bool)
            })
            if hasEmptyParameterOverload {
                return true
            }
            importer.addSemanticDiagnostic(AlphaTexDiagnostic(severity: AlphaTexDiagnosticsSeverity.Error, code: AlphaTexDiagnosticCode.AT219, message: "Error parsing arguments: no overload matched arguments \((AlphaTex1MetaDataReader.generateSignaturesFromArguments(nil)).toTemplate()). Signatures: \((AlphaTex1MetaDataReader.generateSignatures(signatures)).toTemplate())", start: parent.start, end: parent.end))
            return false
        }
        if TypeHelper.isTruthy(args!.validated) {
            return true
        }
        var error: Bool = false
        let candidates: Map<Double, SignatureResolutionInfo> = Map<Double, SignatureResolutionInfo>(signatures.map({ (v: AlphaTexSignatureDefinition, i: Double) -> (Double, SignatureResolutionInfo) in
            return (i, (SignatureResolutionInfo(signature: v, parameterIndex: 0.0, parameterHasValues: false, parameterValueMatches: 0.0) as SignatureResolutionInfo))
        }))
        let parseFull: Bool = importer.parseMode == AlphaTexParseMode.Full
        let trackValue: (any IAlphaTexAstNode, Double) -> Void = parseFull ? { (value: any IAlphaTexAstNode, overloadIndex: Double) in
            let overload: SignatureResolutionInfo = candidates.get(overloadIndex)!
            let valueNode: any IAlphaTexArgumentValue = (value as! any IAlphaTexArgumentValue)
            if !TypeHelper.isTruthy(valueNode.parameterIndices) {
                valueNode.parameterIndices = Map<Double, Double>()
            }
            valueNode.parameterIndices!.set(overloadIndex, overload.parameterIndex)
        } : { (_value: any IAlphaTexAstNode, _overloadIndex: Double) in
        }
        for value in args!.arguments {
            try AlphaTex1MetaDataReader.filterSignatureCandidates(candidates, value, false, trackValue)
            if candidates.size == 0.0 {
                break
            }
        }
        let allCandidates: List<(Double, SignatureResolutionInfo)>? = parseFull ? Array.from(candidates.entries()) : nil
        AlphaTex1MetaDataReader.filterIncompleteCandidates(candidates)
        if candidates.size == 0.0 {
            importer.addSemanticDiagnostic(AlphaTexDiagnostic(severity: AlphaTexDiagnosticsSeverity.Error, code: AlphaTexDiagnosticCode.AT219, message: "Error parsing arguments: no overload matched arguments \((AlphaTex1MetaDataReader.generateSignaturesFromArguments(args!.arguments)).toTemplate()). Signatures:\n\((AlphaTex1MetaDataReader.generateSignatures(signatures)).toTemplate())", start: args!.start, end: args!.end))
            error = true
        }
        if TypeHelper.isTruthy(allCandidates) {
            AlphaTex1MetaDataReader.sortCandidates(allCandidates!)
            args!.signatureCandidateIndices = allCandidates!.map({ (c: (Double, SignatureResolutionInfo)) -> Double in
                return c.0
            })
        }
        return !error
    }

    private func _headerFooterStyle(_ importer: any IAlphaTexImporter, _ score: Score, _ element: ScoreSubElement, _ metaData: AlphaTexMetaDataNode, _ startIndex: Double = 1.0) throws {
