        } else {
            let c: NumberedStaffConfig = staff?.numberedConfig ?? stylesheet?.numberedConfig ?? NumberedStaffConfig()
            try c.timeSignature = element("ts", c.timeSignature)
            try c.barNumber = barNumber(c.barNumber)
